  // Sammanslagning av texturer
  'Flera texturer i modellen': ['Flere teksturer i modellen', 'Flere teksturer i modellen', 'Mallissa useita tekstuureja', 'Multiple textures in model'],
  'Modellen använder {n} texturer, men GTA laddar bara en per färgvariant – resten blir fel in game. Slå ihop dem till en.': ['Modellen bruker {n} teksturer, men GTA laster bare én per fargevariant – resten blir feil i spillet. Slå dem sammen til én.', 'Modellen bruger {n} teksturer, men GTA indlæser kun én pr. farvevariant – resten bliver forkert i spillet. Læg dem sammen til én.', 'Malli käyttää {n} tekstuuria, mutta GTA lataa vain yhden värivaihtoehtoa kohden – muut näkyvät väärin pelissä. Yhdistä ne yhdeksi.', 'The model uses {n} textures, but GTA loads only one per color variant – the rest look wrong in game. Merge them into one.'],
  'Huvudtextur (dess färgvarianter behålls)': ['Hovedtekstur (fargevariantene beholdes)', 'Hovedtekstur (farvevarianterne bevares)', 'Päätekstuuri (sen värivaihtoehdot säilyvät)', 'Main texture (its color variants are kept)'],
  'Atlas': ['Atlas', 'Atlas', 'Atlas', 'Atlas'],
  'Slå ihop till en textur': ['Slå sammen til én tekstur', 'Læg sammen til én tekstur', 'Yhdistä yhdeksi tekstuuriksi', 'Merge into one texture'],
  'Välj en bild för: {k}': ['Velg et bilde for: {k}', 'Vælg et billede til: {k}', 'Valitse kuva kohteelle: {k}', 'Choose an image for: {k}'],
  'Huvudtexturens färgvarianter behålls – varje variant får en egen sammanslagen textur. Normal- och spec-kartor slås ihop på samma sätt.': ['Hovedteksturens fargevarianter beholdes – hver variant får sin egen sammenslåtte tekstur. Normal- og spec-kart slås sammen på samme måte.', 'Hovedteksturens farvevarianter bevares – hver variant får sin egen sammenlagte tekstur. Normal- og spec-kort lægges sammen på samme måde.', 'Päätekstuurin värivaihtoehdot säilyvät – jokainen saa oman yhdistetyn tekstuurin. Normal- ja spec-kartat yhdistetään samalla tavalla.', "The main texture's color variants are kept – each variant gets its own merged texture. Normal and spec maps are merged the same way."],
  'Texturerna är ihopslagna till en. Plagget fungerar nu med en .ytd per färgvariant.': ['Teksturene er slått sammen til én. Plagget fungerer nå med én .ytd per fargevariant.', 'Teksturerne er lagt sammen til én. Tøjstykket virker nu med én .ytd pr. farvevariant.', 'Tekstuurit on yhdistetty yhdeksi. Vaate toimii nyt yhdellä .ytd:llä värivaihtoehtoa kohden.', 'The textures are merged into one. The item now works with one .ytd per color variant.'],

  // Guide
  'Kom igång': ['Kom i gang', 'Kom i gang', 'Aloita', 'Get started'],
  'Fem steg från GTA till din server.': ['Fem steg fra GTA til serveren din.', 'Fem trin fra GTA til din server.', 'Viisi vaihetta GTA:sta palvelimellesi.', 'Five steps from GTA to your server.'],
  'Hämta gubbarna': ['Hent figurene', 'Hent figurerne', 'Hae hahmot', 'Load the peds'],
  'Gubbarna hämtas automatiskt ur ditt GTA V första gången appen startar, med originalskelettet.': ['Figurene hentes automatisk fra ditt GTA V første gang appen starter, med originalskjelettet.', 'Figurerne hentes automatisk fra dit GTA V første gang, appen starter, med det originale skelet.', 'Hahmot haetaan automaattisesti GTA V:stäsi, kun sovellus käynnistyy ensimmäisen kerran, alkuperäisellä luurangolla.', 'The peds are loaded automatically from your GTA V the first time the app starts, with the original skeleton.'],
  'Dra in kläder': ['Dra inn klær', 'Træk tøj ind', 'Vedä vaatteet sisään', 'Drop in clothes'],
  'Släpp .ydd/.ytd-filer eller hela mappar i listan till vänster. Kategori, kön och paket läses av filnamnen.': ['Slipp .ydd/.ytd-filer eller hele mapper i listen til venstre. Kategori, kjønn og pakke leses fra filnavnene.', 'Slip .ydd/.ytd-filer eller hele mapper i listen til venstre. Kategori, køn og pakke læses fra filnavnene.', 'Pudota .ydd/.ytd-tiedostoja tai kokonaisia kansioita vasempaan listaan. Kategoria, sukupuoli ja paketti luetaan tiedostonimistä.', 'Drop .ydd/.ytd files or whole folders in the list on the left. Category, gender and pack are read from the file names.'],
  'Dela upp i paket': ['Del opp i pakker', 'Del op i pakker', 'Jaa paketteihin', 'Split into packs'],
  'Skapa paket (t.ex. polis, ambulans) och ge dem egna namn för kille och tjej.': ['Lag pakker (f.eks. politi, ambulanse) og gi dem egne navn for gutt og jente.', 'Opret pakker (f.eks. politi, ambulance) og giv dem egne navne til fyr og pige.', 'Luo paketteja (esim. poliisi, ambulanssi) ja anna niille omat nimet miehelle ja naiselle.', 'Create packs (e.g. police, ambulance) and give them their own names for male and female.'],
  'Redigera': ['Rediger', 'Redigér', 'Muokkaa', 'Edit'],
  'Ta bort loggor, måla, lägg till text, nya färgvarianter eller slå ihop texturer.': ['Fjern logoer, mal, legg til tekst, nye fargevarianter eller slå sammen teksturer.', 'Fjern logoer, mal, tilføj tekst, nye farvevarianter eller læg teksturer sammen.', 'Poista logoja, maalaa, lisää tekstiä, uusia värivaihtoehtoja tai yhdistä tekstuureja.', 'Remove logos, paint, add text, new color variants or merge textures.'],
  'Exportera': ['Eksporter', 'Eksportér', 'Vie', 'Export'],
  'Exportera till FiveM, lägg mappen i resources/ och skriv ensure i server.cfg.': ['Eksporter til FiveM, legg mappen i resources/ og skriv ensure i server.cfg.', 'Eksportér til FiveM, læg mappen i resources/ og skriv ensure i server.cfg.', 'Vie FiveMiin, laita kansio resources/-kansioon ja kirjoita ensure server.cfg-tiedostoon.', 'Export to FiveM, put the folder in resources/ and add ensure to server.cfg.'],

  // Paket
  'Klädpaket': ['Klespakker', 'Tøjpakker', 'Vaatepaketit', 'Clothing packs'],
  'Dela upp kläderna i egna paket, t.ex. polis och ambulans. Varje paket får egna filer för kille och tjej.': ['Del klærne opp i egne pakker, f.eks. politi og ambulanse. Hver pakke får egne filer for gutt og jente.', 'Del tøjet op i egne pakker, f.eks. politi og ambulance. Hver pakke får egne filer til fyr og pige.', 'Jaa vaatteet omiin paketteihin, esim. poliisi ja ambulanssi. Jokainen paketti saa omat tiedostot miehelle ja naiselle.', 'Split the clothes into their own packs, e.g. police and ambulance. Each pack gets its own files for male and female.'],
  'Nytt paket': ['Ny pakke', 'Ny pakke', 'Uusi paketti', 'New pack'],
  'Namnmall': ['Navnemal', 'Navneskabelon', 'Nimimalli', 'Name template'],
  'Ta bort paketet (plaggen flyttas till första paketet)': ['Fjern pakken (plaggene flyttes til første pakke)', 'Fjern pakken (tøjet flyttes til første pakke)', 'Poista paketti (vaatteet siirretään ensimmäiseen pakettiin)', 'Remove the pack (items move to the first pack)'],
  'Ta bort paketet "{n}"?': ['Fjerne pakken «{n}»?', 'Fjern pakken "{n}"?', 'Poistetaanko paketti "{n}"?', 'Remove the pack "{n}"?'],
  'plagg': ['plagg', 'tøjstykker', 'vaatetta', 'items'],
  'Tips: markera flera plagg i listan med Ctrl+klick eller Skift+klick och flytta dem till ett annat paket med knappen som visas längst ner.': ['Tips: merk flere plagg i listen med Ctrl+klikk eller Shift+klikk og flytt dem til en annen pakke med knappen som vises nederst.', 'Tip: markér flere tøjstykker i listen med Ctrl+klik eller Shift+klik, og flyt dem til en anden pakke med knappen, der vises nederst.', 'Vinkki: valitse useita vaatteita listasta Ctrl+klikkauksella tai Vaihto+klikkauksella ja siirrä ne toiseen pakettiin alareunaan ilmestyvällä painikkeella.', 'Tip: select several items in the list with Ctrl+click or Shift+click and move them to another pack with the button that appears at the bottom.'],
